    {
      "rung": 22,
      "purpose": "Advance from VENT to UNCLAMP when vent timer done and pressure is safe"
    },
    {
      "rung": 23,
      "purpose": "Advance from UNCLAMP to DONE when clamp is fully open"
    },
    {
      "rung": 24,
      "purpose": "Reset busy flag and clear DONE step when pallet leaves test position"
    },
    {
      "rung": 25,
      "purpose": "Energize clamp close solenoid during active cycle steps"
    },
    {
      "rung": 26,
      "purpose": "Energize fill valve during FILL step unless faulted"
    },
    {
      "rung": 27,
      "purpose": "Energize vent valve during VENT step or upon overpressure fault"
    },
    {
      "rung": 28,
      "purpose": "Output PASS or FAIL signals to line controller when DONE"
    },
    {
